<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/auth.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$code=trim($_POST['code']??''); if($name&&$code){try{$s=$pdo->prepare("INSERT INTO statuses(name,code) VALUES(?,?)");$s->execute([$name,$code]);flash('success','Created successfully.');}catch(Exception $e){flash('danger','Could not create record.');}}}
$page_title='Statuses';$rows=$pdo->query("SELECT * FROM statuses ORDER BY name")->fetchAll();include __DIR__.'/../includes/header.php';?>
<div class="admin-layout py-3"><?php include __DIR__.'/../includes/sidebar.php';?><section><div class="mb-4"><h2 class="section-title">Statuses</h2></div><div class="glass-panel p-4 mb-4"><form method="post" class="row g-2"><div class="col-md-5"><input class="form-control" name="name" placeholder="Name" required></div><div class="col-md-5"><input class="form-control" name="code" placeholder="Code" required></div><div class="col-md-2"><button class="btn btn-primary-glass w-100">Add</button></div></form></div><div class="glass-panel table-wrap"><table class="table"><thead><tr><th>ID</th><th>Name</th><th>Code</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['name'])?></td><td><?=e($r['code'])?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php include __DIR__.'/../includes/footer.php';?>